import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        long[] queries = new long[(int) q];
        for (int i = 0; i < queries.length; i++) queries[i] = Long.parseLong(next());

        int limit = 0;
        for (long x : queries) limit = Math.max(limit, (int) x);
        long[] ugly = new long[limit];
        ugly[0] = 1;
        int i2 = 0, i3 = 0, i5 = 0;
        for (int k = 1; k < limit; k++) {
            long nxt = Math.min(ugly[i2] * 2, Math.min(ugly[i3] * 3, ugly[i5] * 5));
            ugly[k] = nxt;
            if (nxt == ugly[i2] * 2) i2++;
            if (nxt == ugly[i3] * 3) i3++;
            if (nxt == ugly[i5] * 5) i5++;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) out.append(i > 0 ? " " : "").append(ugly[(int) queries[i] - 1]);
        System.out.println(out);
    }
}
